from pathlib import Path

path = Path('apps/admin/app/admin-console.tsx')
text = path.read_text()

text = text.replace(
    "type ServiceProvider={id:string;businessName:string;contactName?:string|null;phone:string;email?:string|null;verification:'PENDING'|'VERIFIED'|'REJECTED'|'SUSPENDED';societies:ServiceProviderApproval[]}",
    "type ServiceProvider={id:string;businessName:string;contactName?:string|null;phone:string;email?:string|null;description?:string|null;verification:'PENDING'|'VERIFIED'|'REJECTED'|'SUSPENDED';societies:ServiceProviderApproval[]}",
)

old_roles = """const adminRoles=new Set(['SUPER_ADMIN','SOCIETY_ADMIN','COMMITTEE_MEMBER','FACILITY_MANAGER','ACCOUNTANT'])
const billingRoles=new Set(['SUPER_ADMIN','SOCIETY_ADMIN','ACCOUNTANT'])
const marketplaceRoles=new Set(['SUPER_ADMIN','SOCIETY_ADMIN','FACILITY_MANAGER'])
const residentManagementRoles=new Set(['SUPER_ADMIN','SOCIETY_ADMIN'])
const workforceRoles=new Set(['SUPER_ADMIN','SOCIETY_ADMIN','FACILITY_MANAGER'])

function viewsForRole(role:string):View[]{
  if(role==='ACCOUNTANT')return ['billing']
  return ['overview',...(residentManagementRoles.has(role)?['residents' as const]:[]),'gates',...(workforceRoles.has(role)?['workforce' as const]:[]),...(marketplaceRoles.has(role)?['marketplace' as const]:[]),'sos','helpdesk','notices',...(billingRoles.has(role)?['billing' as const]:[])]
}
"""
new_roles = """const roleViews:Readonly<Record<string,readonly View[]>>={
  SUPER_ADMIN:['overview','residents','gates','workforce','marketplace','sos','helpdesk','notices','billing'],
  SOCIETY_ADMIN:['overview','residents','gates','workforce','marketplace','sos','helpdesk','notices','billing'],
  COMMITTEE_MEMBER:['overview','gates','sos','helpdesk','notices'],
  FACILITY_MANAGER:['overview','gates','workforce','marketplace','sos','helpdesk','notices'],
  ACCOUNTANT:['billing'],
  SECURITY_SUPERVISOR:['gates','sos'],
}
const adminRoles=new Set(Object.keys(roleViews))

function viewsForRole(role:string):View[]{return [...(roleViews[role]??[])]}
"""
if old_roles not in text:
    raise SystemExit('role block not found')
text = text.replace(old_roles, new_roles)

old_accept = "const accept=(next:Session)=>{if(!adminRoles.has(next.role))throw new Error('This role does not have Society Admin access');sessionStorage.setItem('aaraagate.admin.session',JSON.stringify(next));setView(next.role==='ACCOUNTANT'?'billing':'overview');setSession(next)}"
new_accept = "const accept=(next:Session)=>{const allowed=viewsForRole(next.role);if(!adminRoles.has(next.role)||allowed.length===0)throw new Error('This role does not have Admin or operations-console access');sessionStorage.setItem('aaraagate.admin.session',JSON.stringify(next));setView(allowed[0]);setSession(next)}"
if old_accept not in text:
    raise SystemExit('accept block not found')
text = text.replace(old_accept, new_accept)

old_verify = "const verify=(e:FormEvent)=>{e.preventDefault();void run(async()=>{const result=await api<Record<string,unknown>>('/auth/otp/verify',{method:'POST',body:JSON.stringify({challengeId:challenge,code:otp})});const options=((result.memberships as Membership[])??[]).filter(m=>adminRoles.has(m.role));if(!options.length)throw new Error('No active Society Admin membership');setUserId(String(result.userId));setMemberships(options);if(result.session&&options.length===1)onSession(sessionFrom(result,options[0]));else{setToken(String(result.selectionToken??''));setStage('society')}})}"
new_verify = "const verify=(e:FormEvent)=>{e.preventDefault();void run(async()=>{const result=await api<Record<string,unknown>>('/auth/otp/verify',{method:'POST',body:JSON.stringify({challengeId:challenge,code:otp})});const options=((result.memberships as Membership[])??[]).filter(m=>adminRoles.has(m.role)&&viewsForRole(m.role).length>0);if(!options.length)throw new Error('No active Admin or operations-console membership');setUserId(String(result.userId));setMemberships(options);if(result.session&&options.length===1)onSession(sessionFrom(result,options[0]));else{setToken(String(result.selectionToken??''));setStage('society')}})}"
if old_verify not in text:
    raise SystemExit('login verify block not found')
text = text.replace(old_verify, new_verify)
text = text.replace('<h1>Admin sign in</h1><p>Secure society-scoped operational access.</p>', '<h1>Admin & operations sign in</h1><p>Secure society-scoped access based on your assigned capabilities.</p>')
text = text.replace("const canAudit=['SUPER_ADMIN','SOCIETY_ADMIN','COMMITTEE_MEMBER'].includes(session.role)", "const canAudit=['SUPER_ADMIN','SOCIETY_ADMIN','COMMITTEE_MEMBER','SECURITY_SUPERVISOR'].includes(session.role)")

start = text.index('function Marketplace({session}:{session:Session}){')
end = text.index('\nfunction Billing({session}:{session:Session}){', start)
marketplace = r'''function Marketplace({session}:{session:Session}){
  const[catalog,setCatalog]=useState<ServiceCatalog>({categories:[],providers:[],offerings:[]}),[bookings,setBookings]=useState<ServiceBooking[]>([]),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[form,setForm]=useState<'provider'|'category'|'offering'|null>(null)
  const[businessName,setBusinessName]=useState(''),[contactName,setContactName]=useState(''),[phone,setPhone]=useState('+91'),[email,setEmail]=useState(''),[providerDescription,setProviderDescription]=useState('')
  const[providerId,setProviderId]=useState(''),[categoryId,setCategoryId]=useState(''),[offeringName,setOfferingName]=useState(''),[price,setPrice]=useState(''),[duration,setDuration]=useState(''),[offeringDescription,setOfferingDescription]=useState('')
  const[categoryName,setCategoryName]=useState(''),[categorySlug,setCategorySlug]=useState(''),[sortOrder,setSortOrder]=useState('0')
  const canPlatformCatalog=session.role==='SUPER_ADMIN'
  const load=useCallback(async()=>{setLoading(true);setError('');try{const[c,b]=await Promise.all([api<ServiceCatalog>('/services-marketplace/admin/catalog',{},session),api<ServiceBooking[]>('/services-marketplace/admin/bookings',{},session)]);setCatalog(c);setBookings(b)}catch(e){setError(e instanceof Error?e.message:'Marketplace operations could not be loaded')}finally{setLoading(false)}},[session])
  useEffect(()=>{void load()},[load])
  const createProvider=async(e:FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await api('/services-marketplace/admin/providers',{method:'POST',body:JSON.stringify({businessName:businessName.trim(),contactName:contactName.trim()||undefined,phone:phone.trim(),email:email.trim()||undefined,description:providerDescription.trim()||undefined})},session);setBusinessName('');setContactName('');setPhone('+91');setEmail('');setProviderDescription('');setForm(null);await load()}catch(e){setError(e instanceof Error?e.message:'Provider could not be onboarded')}finally{setBusy(false)}}
  const verifyProvider=async(provider:ServiceProvider)=>{if(!canPlatformCatalog)return;if(!confirm(`Platform-verify ${provider.businessName}?`))return;setBusy(true);setError('');try{await api(`/platform/services/providers/${provider.id}/verify`,{method:'POST',body:'{}'},session);await load()}catch(e){setError(e instanceof Error?e.message:'Provider verification failed')}finally{setBusy(false)}}
  const approve=async(provider:ServiceProvider)=>{const entered=prompt(`Commission percentage for ${provider.businessName}`,'10');if(entered===null)return;const percentage=Number(entered);if(!Number.isFinite(percentage)||percentage<0||percentage>100){setError('Commission must be between 0% and 100%');return}setBusy(true);setError('');try{await api(`/services-marketplace/admin/providers/${provider.id}/approve`,{method:'POST',body:JSON.stringify({commissionBps:Math.round(percentage*100)})},session);await load()}catch(e){setError(e instanceof Error?e.message:'Provider approval failed')}finally{setBusy(false)}}
  const createCategory=async(e:FormEvent)=>{e.preventDefault();if(!canPlatformCatalog)return;const order=Number(sortOrder);if(!Number.isInteger(order)){setError('Sort order must be a whole number');return}setBusy(true);setError('');try{await api('/services-marketplace/admin/categories',{method:'POST',body:JSON.stringify({name:categoryName.trim(),slug:categorySlug.trim(),sortOrder:order})},session);setCategoryName('');setCategorySlug('');setSortOrder('0');setForm(null);await load()}catch(e){setError(e instanceof Error?e.message:'Category could not be created')}finally{setBusy(false)}}
  const createOffering=async(e:FormEvent)=>{e.preventDefault();if(!canPlatformCatalog)return;const rupees=Number(price);if(!Number.isFinite(rupees)||rupees<0){setError('Price must be zero or more');return}setBusy(true);setError('');try{await api('/services-marketplace/admin/offerings',{method:'POST',body:JSON.stringify({providerId,categoryId,name:offeringName.trim(),pricePaise:Math.round(rupees*100),description:offeringDescription.trim()||undefined,durationMinutes:duration?Number(duration):undefined})},session);setProviderId('');setCategoryId('');setOfferingName('');setPrice('');setDuration('');setOfferingDescription('');setForm(null);await load()}catch(e){setError(e instanceof Error?e.message:'Offering could not be created')}finally{setBusy(false)}}
  const progress=async(booking:ServiceBooking,action:'confirm'|'complete')=>{if(!confirm(`${action==='confirm'?'Confirm':'Complete'} ${booking.offering.name} for ${booking.residentUser.name}?`))return;setBusy(true);setError('');try{await api(`/services-marketplace/admin/bookings/${booking.id}/${action}`,{method:'POST',body:'{}'},session);await load()}catch(e){setError(e instanceof Error?e.message:'Booking could not be updated')}finally{setBusy(false)}}
  const approved=catalog.providers.filter(p=>p.societies[0]?.status==='APPROVED'),awaitingVerification=catalog.providers.filter(p=>p.societies[0]?.status==='PENDING'&&p.verification==='PENDING'),pending=bookings.filter(b=>b.status==='REQUESTED'),active=bookings.filter(b=>b.status==='CONFIRMED'||b.status==='IN_PROGRESS')
  const currency=(paise:number)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(paise/100)
  const providerContact=(provider:ServiceProvider)=>[provider.contactName,provider.phone,provider.email].filter(Boolean).join(' · ')||'Platform verified provider — contact details available after society association'
  return <><Header title="Service marketplace" society="Provider onboarding, verification, approval and booking operations"/><div className="grid"><Metric label="Approved providers" value={approved.length}/><Metric label="Awaiting verification" value={awaitingVerification.length}/><Metric label="Booking requests" value={pending.length}/><Metric label="Active bookings" value={active.length}/></div><div className="toolbar billingToolbar"><p>Provider submission is society-scoped. Platform verification is separate from society approval. Global service categories and offerings are Super Admin controls so one society cannot change another society&apos;s catalog.</p><div className="buttons"><button onClick={()=>setForm(form==='provider'?null:'provider')}>Onboard provider</button>{canPlatformCatalog&&<button onClick={()=>setForm(form==='category'?null:'category')}>Add category</button>}{canPlatformCatalog&&<button className="primary" disabled={approved.length===0||catalog.categories.length===0} onClick={()=>setForm(form==='offering'?null:'offering')}>Add offering</button>}<button disabled={busy} onClick={()=>void load()}>Refresh</button></div></div>{error&&<div className="error">{error}</div>}{form==='provider'&&<form className="panel form" onSubmit={createProvider}><label>Business name<input value={businessName} onChange={e=>setBusinessName(e.target.value)} minLength={2} required/></label><label>Contact name<input value={contactName} onChange={e=>setContactName(e.target.value)}/></label><label>Mobile<input value={phone} onChange={e=>setPhone(e.target.value)} required/></label><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)}/></label><label className="wide">Description<textarea value={providerDescription} onChange={e=>setProviderDescription(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?'Saving…':'Submit for platform verification'}</button></form>}{form==='category'&&canPlatformCatalog&&<form className="panel form" onSubmit={createCategory}><label>Category name<input value={categoryName} onChange={e=>{setCategoryName(e.target.value);if(!categorySlug)setCategorySlug(e.target.value.toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''))}} minLength={2} required/></label><label>Slug<input value={categorySlug} onChange={e=>setCategorySlug(e.target.value.toLowerCase().replace(/[^a-z0-9-]/g,''))} required/></label><label>Sort order<input type="number" value={sortOrder} onChange={e=>setSortOrder(e.target.value)} required/></label><button className="primary" disabled={busy}>{busy?'Saving…':'Create platform category'}</button></form>}{form==='offering'&&canPlatformCatalog&&<form className="panel form" onSubmit={createOffering}><label>Approved provider<select value={providerId} onChange={e=>setProviderId(e.target.value)} required><option value="">Select provider</option>{approved.map(p=><option key={p.id} value={p.id}>{p.businessName}</option>)}</select></label><label>Category<select value={categoryId} onChange={e=>setCategoryId(e.target.value)} required><option value="">Select category</option>{catalog.categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Offering name<input value={offeringName} onChange={e=>setOfferingName(e.target.value)} required/></label><label>Price (₹)<input type="number" min="0" step="0.01" value={price} onChange={e=>setPrice(e.target.value)} required/></label><label>Duration (minutes)<input type="number" min="1" value={duration} onChange={e=>setDuration(e.target.value)}/></label><label className="wide">Description<textarea value={offeringDescription} onChange={e=>setOfferingDescription(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?'Saving…':'Create platform offering'}</button></form>}{loading?<section className="panel"><Empty text="Loading marketplace operations…"/></section>:<><div className="relationshipGrid"><section className="panel relationshipPanel"><h2>Provider directory</h2>{catalog.providers.length===0?<Empty text="No providers onboarded"/>:catalog.providers.map(provider=>{const approval=provider.societies[0];return <article className="relationshipCard" key={provider.id}><div><b>{provider.businessName}</b><span>{providerContact(provider)}</span>{provider.description&&<small>{provider.description}</small>}<div><Badge text={provider.verification}/><Badge text={approval?.status??'NOT APPROVED'}/>{approval?.status==='APPROVED'&&<Badge text={`${approval.commissionBps/100}% COMMISSION`}/>}</div></div><div className="buttons">{provider.verification==='PENDING'&&approval?.status==='PENDING'&&canPlatformCatalog&&<button className="primary" disabled={busy} onClick={()=>void verifyProvider(provider)}>Platform verify</button>}{provider.verification==='PENDING'&&approval?.status==='PENDING'&&!canPlatformCatalog&&<small>Awaiting platform verification</small>}{provider.verification==='VERIFIED'&&approval?.status!=='APPROVED'&&<button disabled={busy} onClick={()=>void approve(provider)}>Approve for society</button>}</div></article>})}</section><section className="panel relationshipPanel"><h2>Live offerings</h2>{catalog.offerings.length===0?<Empty text="No offerings available"/>:catalog.offerings.map(offering=><article className="relationshipCard" key={offering.id}><div><b>{offering.name}</b><span>{offering.provider.businessName} · {offering.category.name}</span><div><Badge text={currency(offering.pricePaise)}/>{offering.durationMinutes&&<Badge text={`${offering.durationMinutes} MIN`}/>}</div></div></article>)}</section></div><section className="panel relationshipPanel billingToolbar"><h2>Society booking queue</h2>{bookings.length===0?<Empty text="No service bookings"/>:bookings.map(booking=><article className="relationshipCard" key={booking.id}><div><b>{booking.offering.name}</b><span>{booking.residentUser.name} · {booking.unit.building.name} · {booking.unit.number}</span><span>{booking.provider.businessName} · {new Date(booking.scheduledFrom).toLocaleString('en-IN')} → {new Date(booking.scheduledUntil).toLocaleString('en-IN')}</span><div><Badge text={booking.status}/><Badge text={currency(booking.servicePricePaise)}/></div></div><div className="buttons">{booking.status==='REQUESTED'&&<button className="primary" disabled={busy} onClick={()=>void progress(booking,'confirm')}>Confirm</button>}{['CONFIRMED','IN_PROGRESS'].includes(booking.status)&&<button className="primary" disabled={busy} onClick={()=>void progress(booking,'complete')}>Complete</button>}</div></article>)}</section></>}</>
}
'''
text = text[:start] + marketplace + text[end:]
path.write_text(text)
